import sys

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    n = int(sys.stdin.readline().strip())
    a = read_ints()

    dp = [1] * n
    prev = [-1] * n

    # Find the length of the longest increasing subsequence
    for i in range(n):
        for j in range(i):
            if a[j] < a[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                prev[i] = j

    # Find the maximum length of the LIS
    max_len = max(dp)

    # Determine the groups for each index
    group = ['0'] * n
    for i in range(n):
        if dp[i] == 1:
            group[i] = '3'
        elif dp[i] == max_len:
            group[i] = '1'
        else:
            group[i] = '2'

    # Check if the index belongs to every longest increasing subsequence
    for i in range(n):
        if dp[i] == max_len:
            j = i
            while j != -1:
                if group[j] == '1':
                    group[j] = '3'
                j = prev[j]

    # Output the result
    print(''.join(group))

if __name__ == "__main__":
    main()
